package com.turing.app.api.notification.controller;
import static org.assertj.core.api.Assertions.assertThat;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.csrf;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import com.jayway.jsonpath.JsonPath;import com.turing.app.api.auth.service.AuthMailService;import com.turing.app.api.notification.mail.EmailSender;import com.turing.app.api.user.repository.UserRepository;import jakarta.servlet.http.Cookie;import java.time.*;import java.util.*;import java.util.concurrent.ConcurrentHashMap;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.*;import org.springframework.boot.testcontainers.service.connection.ServiceConnection;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.context.annotation.*;import org.springframework.http.MediaType;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.ActiveProfiles;import org.testcontainers.containers.PostgreSQLContainer;import org.testcontainers.junit.jupiter.*;
@SpringBootTest@AutoConfigureMockMvc@Testcontainers@ActiveProfiles("test")@Import(NotificationControllerIT.MailConfig.class)class NotificationControllerIT{@Container@ServiceConnection static PostgreSQLContainer<?>postgres=new PostgreSQLContainer<>("postgres:17-alpine");@Autowired org.springframework.test.web.servlet.MockMvc mvc;@Autowired Mail mail;@Autowired UserRepository users;@Autowired JdbcTemplate jdbc;
 @Test void sendsCampaignInBackgroundTracksRecipientsAndProtectsNotifications()throws Exception{Cookie admin=admin("mail-admin@example.com"),student=session("mail-student@example.com"),other=session("mail-other@example.com");UUID studentId=users.findByEmailIgnoreCase("mail-student@example.com").orElseThrow().getId();String campaign=JsonPath.read(mvc.perform(post("/api/admin/email-campaigns").with(csrf()).cookie(admin).contentType(MediaType.APPLICATION_JSON).content("{\"subject\":\"Duyuru\",\"body\":\"Merhaba\",\"userIds\":[\""+studentId+"\"]}")).andExpect(status().isCreated()).andExpect(jsonPath("$.status").value("DRAFT")).andReturn().getResponse().getContentAsString(),"$.id");mvc.perform(post("/api/admin/email-campaigns/"+campaign+"/send").with(csrf()).cookie(admin).contentType(MediaType.APPLICATION_JSON).content("{\"version\":0}")).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("SENDING"));for(int i=0;i<50&&jdbc.queryForObject("select count(*) from email_recipients where campaign_id=? and status='SENT'",Integer.class,UUID.fromString(campaign))==0;i++)Thread.sleep(20);assertThat(mail.sent).contains("mail-student@example.com");UUID notification=UUID.randomUUID();jdbc.update("insert into notifications(id,user_id,title,message,type,created_at)values(?,?,?,?,?,?)",notification,studentId,"Test","Mesaj","TEST",OffsetDateTime.now(ZoneOffset.UTC));mvc.perform(get("/api/me/notifications").cookie(student)).andExpect(status().isOk()).andExpect(jsonPath("$[0].id").value(notification.toString()));mvc.perform(patch("/api/me/notifications/"+notification+"/read").with(csrf()).cookie(other)).andExpect(status().isNotFound());mvc.perform(patch("/api/me/notifications/"+notification+"/read").with(csrf()).cookie(student)).andExpect(status().isOk()).andExpect(jsonPath("$.readAt").isNotEmpty());}
 private Cookie admin(String email)throws Exception{session(email);UUID id=users.findByEmailIgnoreCase(email).orElseThrow().getId();jdbc.update("update users set role='ADMIN' where id=?",id);return login(email);}private Cookie session(String email)throws Exception{mvc.perform(post("/api/auth/register").with(csrf()).contentType(MediaType.APPLICATION_JSON).content("{\"email\":\""+email+"\",\"password\":\"strong-pass-123\",\"firstName\":\"Test\",\"lastName\":\"User\"}")).andExpect(status().isCreated());mvc.perform(post("/api/auth/verify-email").with(csrf()).contentType(MediaType.APPLICATION_JSON).content("{\"token\":\""+mail.tokens.get(email)+"\"}")).andExpect(status().isOk());return login(email);}private Cookie login(String email)throws Exception{return mvc.perform(post("/api/auth/login").with(csrf()).contentType(MediaType.APPLICATION_JSON).content("{\"email\":\""+email+"\",\"password\":\"strong-pass-123\"}")).andReturn().getResponse().getCookie("TURING_ACCESS_TOKEN");}
 @TestConfiguration static class MailConfig{@Bean@Primary Mail mail(){return new Mail();}}static class Mail implements AuthMailService,EmailSender{final Map<String,String>tokens=new ConcurrentHashMap<>();final Set<String>sent=ConcurrentHashMap.newKeySet();public void sendVerification(String email,String token){tokens.put(email,token);}public void sendPasswordReset(String email,String token){}public void send(String email,String subject,String body){sent.add(email);}}
}
